    const Vector3 &o = instance->transform.origin;
    hash = hash_murmur3_one_64(uint64_t(int64_t(o.x * 100)) ^ (uint64_t(int64_t(o.y * 100)) << 21) ^ (uint64_t(int64_t(o.z * 100)) << 42), hash);
