        const ActiveLight &light = active_lights[index];
        hash = hash_murmur3_one_64(uint64_t(int64_t(light.position.x * 20)) ^ (uint64_t(int64_t(light.position.y * 20)) << 21) ^ (uint64_t(int64_t(light.position.z * 20)) << 42), hash);
