struct LightOrder {
    const Vector<ActiveLight> *lights = nullptr;
    _FORCE_INLINE_ bool operator()(int a, int b) const {
        const Vector3 &pa = (*lights)[a].position, &pb = (*lights)[b].position;
        if (pa.x != pb.x) return pa.x < pb.x;
        if (pa.y != pb.y) return pa.y < pb.y;
